import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_default():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner()
    result = runner.invoke(cli_raises)
    assert result.exception is not None
    assert isinstance(result.exception, ValueError)

def test_runner_catch_exceptions_false_on_runner():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner(catch_exceptions=False)
    with pytest.raises(ValueError, match="This is an expected error."):
        runner.invoke(cli_raises)

def test_runner_catch_exceptions_override_on_invoke():
    @click.command()
    def cli_raises():
        raise ValueError("This is an expected error.")

    runner = CliRunner(catch_exceptions=True)  # Should be overridden by invoke
    with pytest.raises(ValueError, match="This is an expected error."):
        runner.invoke(cli_raises, catch_exceptions=False)

